// Generator for the A4Tech (Bloody) module device table.
// Usage: node scripts/openrgb/port-a4tech-devices.mjs <openrgb-root> <commit>
// Reads Controllers/A4TechController/{BloodyMouseControllerDetect,
// BloodyB820RControllerDetect} and regenerates
// modules/a4tech/src/devices_table.rs. Do not edit by hand.
import fs from 'node:fs';
import path from 'node:path';
import { execFileSync } from 'node:child_process';

const root = process.argv[2] ?? process.env.OPENRGB_ROOT ?? '../openrgb';
const commit = process.argv[3] ?? 'unknown';
const family = path.join(root, 'Controllers', 'A4TechController');
const read = (rel) => fs.readFileSync(path.join(family, rel), 'utf8');
const mouseDetect = read(path.join('BloodyMouseController', 'BloodyMouseControllerDetect.cpp'));
const b820Detect = read(path.join('BloodyB820RController', 'BloodyB820RControllerDetect.cpp'));

const headerText = fs
  .readdirSync(family, { recursive: true })
  .filter((f) => /\.(cpp|h)$/.test(f))
  .map((f) => fs.readFileSync(path.join(family, f), 'utf8'))
  .join('\n');
const constants = Object.fromEntries(
  [...headerText.matchAll(/#define\s+([A-Z][A-Z0-9_]*)\s+0x([0-9A-Fa-f]+)/g)].map((m) => [
    m[1],
    Number.parseInt(m[2], 16),
  ]),
);
if (constants.A4_TECH_VID == null) throw new Error('A4_TECH_VID not found');
const n = (s) => constants[s.trim()] ?? Number.parseInt(s.trim(), 16);

const rows = [];
for (const kind of [
  { detect: mouseDetect, handler: 'DetectBloodyMouseControllers', protocol: 'mouse' },
  { detect: b820Detect, handler: 'DetectBloodyB820R', protocol: 'b820' },
]) {
  for (const m of kind.detect.matchAll(
    /REGISTER_HID_DETECTOR_(?:IPU|IP)\s*\(\s*"([^"]+)"\s*,\s*([A-Za-z0-9_]+)\s*,\s*A4_TECH_VID\s*,\s*([A-Z][A-Z0-9_]+)\s*,\s*(\d+)\s*,\s*0x([0-9A-Fa-f]+)\s*,\s*0x([0-9A-Fa-f]+)\s*\)/g,
  )) {
    const pid = n(m[3]);
    if (!Number.isFinite(pid)) throw new Error(`unresolved PID ${m[3]} in row ${m[1]}`);
    if (m[2] !== kind.handler) throw new Error(`unexpected handler ${m[2]}`);
    rows.push({
      name: m[1],
      handler: kind.handler,
      vid: constants.A4_TECH_VID,
      pid,
      interface: Number.parseInt(m[4], 10),
      usagePage: Number.parseInt(m[5], 16),
      usage: Number.parseInt(m[6], 16),
      protocol: kind.protocol,
    });
  }
}
if (rows.length !== 6) throw new Error(`expected 6 detector rows, got ${rows.length}`);

// The mouse layouts (W60 Pro / W90 group / MP 50RS zones with physical LED indices)
// and the B820R 104-key data live in RGBController_{BloodyMouse,BloodyB820R}.cpp;
// see modules/a4tech/PROVENANCE.md for the future port.
const out = path.join(process.cwd(), 'modules', 'a4tech', 'src', 'devices_table.rs');
fs.mkdirSync(path.dirname(out), { recursive: true });
const lines = [
  '// SPDX-License-Identifier: GPL-2.0-or-later',
  `// Generated by scripts/openrgb/port-a4tech-devices.mjs from OpenRGB ${commit}; do not edit.`,
  'use crate::table::Detector;',
  '',
  'pub const DETECTORS: &[Detector] = &[',
  ...rows.map((d) =>
    `    Detector { name: ${JSON.stringify(d.name)}, handler: ${JSON.stringify(d.handler)}, vid: 0x${d.vid.toString(16).padStart(4, '0')}, pid: 0x${d.pid.toString(16).padStart(4, '0')}, interface: ${d.interface}, usage_page: 0x${d.usagePage.toString(16)}, usage: 0x${d.usage.toString(16)}, protocol: ${JSON.stringify(d.protocol)} },`,
  ),
  '];',
  '',
];
fs.writeFileSync(out, lines.join('\n'));
execFileSync(
  process.platform === 'win32' ? 'rustfmt.exe' : 'rustfmt',
  [out],
  { stdio: 'ignore' },
);
console.log(`generated ${rows.length} A4Tech HID detectors`);